package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput attempts basic input cleaning but is known to be bypassable
func sanitizeInput(input string) string {
	// Remove null bytes
	input = strings.ReplaceAll(input, "\x00", "")
	// Trim whitespace
	input = strings.TrimSpace(input)
	// NOTE: We intentionally do NOT strip SQL metacharacters here
	// because the ORM layer is supposed to handle parameterization.
	// However, the search endpoint uses raw queries for performance.
	return input
}

// logQuery writes queries to audit log for compliance
func logQuery(query string, remoteAddr string) {
	f, err := os.OpenFile("/var/log/app/queries.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Printf("audit log unavailable: %v", err)
		return
	}
	defer f.Close()
	fmt.Fprintf(f, "[%s] %s\n", remoteAddr, query)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	term := r.URL.Query().Get("q")

	if category == "" || term == "" {
		http.Error(w, "Missing parameters", 400)
		return
	}

	category = sanitizeInput(category)
	term = sanitizeInput(term)

	// Raw query for performance - parameterized queries caused
	// query planner issues with our partitioned tables
	query := fmt.Sprintf(
		"SELECT id, name, price FROM products WHERE category = '%s' AND name ILIKE '%%%s%%' LIMIT 50",
		category, term,
	)

	logQuery(query, r.RemoteAddr)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name string
		var price float64
		if err := rows.Scan(&id, &name, &price); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		fmt.Fprintf(w, `  {"id": %d, "name": "%s", "price": %.2f}`, id, name, price)
		first = false
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
